import React from "react";
import classes from "./Navbar.module.css";
import { NavLink } from "react-router-dom";
import Frends from "./frends-component/Frends";
import Button from "@material-ui/core/Button";

const links = [
  { to: "/profile", label: "Профиль" },
  { to: "/news", label: "Лента" },
  { to: "/message", label: "Сообщения" },
  { to: "/users", label: "Люди" },
  { to: "/music", label: "Музыка" },
  { to: "/settings", label: "Настройки" },
];

const Navbar = (props) => {
  return (
    <nav className={classes.App_nav}>
      {links.map((link) => (
        <NavLink
          key={link.to}
          to={link.to}
          className={classes.navLink}
          activeClassName={classes.activeLink}
        >
          <Button variant="contained" className={classes.itemBtn}>
            {link.label}
          </Button>
        </NavLink>
      ))}

      <div className={classes.frendsItem}>
        <NavLink to="/frends-content" className={classes.frendsContainer}>
          <div className={classes.frendsTitle}>Друзья онлайн</div>
          <Frends store={props.store} />
        </NavLink>
      </div>
    </nav>
  );
};

export default Navbar;
